use vstd::prelude::*;

verus! {

fn concatenate(a: Vec<f32>, b: Vec<f32>) -> Vec<f32>
    ensures
        |result: Vec<f32>| 
            result.len() == a.len() + b.len()
            && forall(|i: nat| i < a.len() ==> result[i] == a[i])
            && forall(|j: nat| j < b.len() ==> result[a.len() + j] == b[j])
{
    // Allocate new vector with capacity for all elements
    let mut result: Vec<f32> = Vec::with_capacity(a.len() + b.len());

    // Append elements of a first
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            result.len() == i,
            forall(|k: nat| k < i ==> result[k] == a[k]),
            result.len() + b.len() == a.len() + b.len(),
        decreases a.len() - i,
    {
        result.push(a[i]);
        i = i + 1;
    }

    // Append elements of b after a
    let mut j: usize = 0;
    while j < b.len()
        invariant
            j <= b.len(),
            result.len() == a.len() + j,
            forall(|k: nat| k < a.len() ==> result[k] == a[k]),
            forall(|l: nat| l < j ==> result[a.len() + l] == b[l]),
        decreases b.len() - j,
    {
        result.push(b[j]);
        j = j + 1;
    }

    result
}

}
